namespace Script {
  public class KpiHelpers {
    public static long TurbTotal = 0, TurbOk = 0, ChlTotal = 0, ChlOk = 0;
    public static int LastShift = 0;
    public static void SampleTurbidity(double ntu) { TurbTotal++; if (ntu <= 0.3) TurbOk++; }
    public static void SampleChlorine(double mgl) { ChlTotal++; if (mgl >= 0.2 && mgl <= 4.0) ChlOk++; }
    public static double TurbPct() { return TurbTotal > 0 ? 100.0 * TurbOk / TurbTotal : 100.0; }
    public static double ChlPct() { return ChlTotal > 0 ? 100.0 * ChlOk / ChlTotal : 100.0; }
    public static void ResetShift() { TurbTotal = 0; TurbOk = 0; ChlTotal = 0; ChlOk = 0; }
  }
}
